CREATE POLICY "plm_media_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'plm-media');
CREATE POLICY "plm_media_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'plm-media' AND public.plm_can_write());
CREATE POLICY "plm_media_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'plm-media' AND public.plm_can_write()) WITH CHECK (bucket_id = 'plm-media' AND public.plm_can_write());
CREATE POLICY "plm_media_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'plm-media' AND public.plm_can_write());